PropertyRemap.Clear();
System.Reflection.PropertyInfo[] properties = typeof(JSkyProfile).GetProperties(System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
for (int i = 0; i < properties.Length; i++)
{
    JAnimatableAttribute attribute = System.Reflection.CustomAttributeExtensions.GetCustomAttribute(properties[i], typeof(JAnimatableAttribute), false) as JAnimatableAttribute;
    if (attribute != null)
        PropertyRemap.Add(properties[i].Name, Shader.PropertyToID("_" + properties[i].Name));
}
